import { existsSync } from 'node:fs'
import { join } from 'node:path'
import { env } from '@server/config/env'
import { drizzle } from 'drizzle-orm/postgres-js'
import { migrate } from 'drizzle-orm/postgres-js/migrator'
import postgres from 'postgres'

/** Applies server/db/migrations (generated by `bun run db:generate`). Never generates. */
const migrationsFolder = join(import.meta.dir, '../db/migrations')

export async function runMigrations(url = env.DATABASE_URL) {
  if (!existsSync(join(migrationsFolder, 'meta/_journal.json'))) {
    throw new Error(`No migrations found in ${migrationsFolder}. Run "bun run db:generate".`)
  }
  const client = postgres(url, { max: 1, onnotice: () => {} })
  try {
    await migrate(drizzle({ client }), { migrationsFolder })
  } finally {
    await client.end({ timeout: 5 })
  }
}

if (import.meta.main) {
  runMigrations()
    .then(() => console.log('Migrations applied'))
    .catch((error: unknown) => {
      console.error('Migration failed:', error instanceof Error ? error.message : error)
      process.exit(1)
    })
}
